import { dirname } from 'node:path';
import { testAction } from '../../actions/functions/test.js';
import config from '../../config.js';
import { STEP_PHASE_GLYPH } from '../../constants.js';
import { resolveDeployedResources } from '../../utils/blueprints/resolve-deployed-resources.js';
import { createDurableJsonCollector } from '../../utils/functions/durable-logs.js';
import { findFunctionInResources, getFunctionNames } from '../../utils/functions/find.js';
import { runFunction } from '../../utils/functions/invoke/nested.js';
import { buildContext, buildInvokeOptions, collectInvokeInput, defaultInvocationDeps, resolveInvocationPlan, } from '../../utils/functions/invoke/resolve-invoke-type.js';
import { createTracedFetch } from '../../utils/traced-fetch.js';
import { isEventType, } from '../../utils/types.js';
export async function functionTestCore(options) {
    const { blueprint, log, error, args, flags, helpText } = options;
    const { name: fnName } = args;
    const { event, timeout, api, 'with-user-token': withUserToken, 'no-wait': noWait } = flags;
    const { 'project-id': projectId = blueprint?.projectId, 'organization-id': organizationId = blueprint?.organizationId, } = flags;
    if (!fnName) {
        const functionNames = getFunctionNames(blueprint.resources);
        const validNames = functionNames.length > 0
            ? `Valid names are: ${functionNames.join(', ')}`
            : 'No functions are defined in the blueprint.';
        error(`Missing required argument: name\n${validNames}\n`, { exit: false });
        log(helpText);
        return { success: true };
    }
    let eventType;
    if (!event) {
        eventType = 'create';
    }
    else if (isEventType(event)) {
        eventType = event;
    }
    else {
        return {
            success: false,
            error: 'The event must be one of `create`, `update` or `delete`.',
        };
    }
    try {
        const fetchFn = createTracedFetch(log);
        const resource = findFunctionInResources(blueprint.resources, fnName); // throws if not found
        const resolvedResources = await resolveDeployedResources({
            resources: blueprint.resources,
            stackId: blueprint.stackId,
            auth: config.token && blueprint.scopeType && blueprint.scopeId
                ? { token: config.token, scopeType: blueprint.scopeType, scopeId: blueprint.scopeId }
                : undefined,
            fetchFn,
        });
        const input = {
            flags,
            projectId,
            organizationId,
            api,
            apiHost: config.apiUrl,
            token: config.token || undefined,
            withUserToken,
            resources: resolvedResources,
            blueprintFileDir: dirname(blueprint.fileInfo.blueprintFilePath),
            log,
        };
        const plan = resolveInvocationPlan(resource);
        const context = buildContext(plan, input);
        const invokeInput = await collectInvokeInput(plan, input, defaultInvocationDeps);
        const invokeOptions = buildInvokeOptions(plan, invokeInput, eventType);
        // Records each nested context.invoke() so they can be surfaced in order after the spinner resolves.
        const nestedRuns = [];
        let nestedOrder = 0;
        const durableJson = createDurableJsonCollector();
        const onStepEvent = plan.isDurable
            ? (event) => {
                if (flags.json) {
                    durableJson.record(event);
                    return;
                }
                for (const line of renderStepTimeline([event])) {
                    if (line !== null)
                        log(line);
                }
            }
            : undefined;
        /**
         * Re-entrant callback that resolves a nested context.invoke(name, payload):
         * it finds the named function in the same blueprint, reuses the already
         * resolved resources, and runs it via the shared invoke-chain helper (which
         * applies the depth/cycle guard and extends the call stack). Passing itself
         * as onNestedInvoke keeps it recursable. Every run is recorded so it can be
         * surfaced after the spinner resolves, including failed ones — a downstream
         * error is fire-and-forget (it doesn't reject the caller) but is still shown.
         */
        const runNested = async (nestedName, nestedPayload, ctx, depth, callStack) => {
            const order = ++nestedOrder;
            const nestedResource = findFunctionInResources(blueprint.resources, nestedName);
            const result = await runFunction(nestedResource, { payload: nestedPayload, event: 'nested' }, { ...ctx, resources: resolvedResources }, { depth, callStack, onNestedInvoke: runNested });
            nestedRuns.push({ order, name: nestedName, logs: result.logs, error: result.error });
            return result;
        };
        const logNestedRuns = () => {
            for (const run of [...nestedRuns].sort((a, b) => a.order - b.order)) {
                log(`↳ BEGIN: invoke('${run.name}')`);
                // Show any logs received
                if (run.logs?.trim()) {
                    log(run.logs.trim());
                }
                // Before any error occurs
                if (run.error) {
                    log(run.error.stack || run.error.message || run.error.name);
                }
                log(`↳ END: invoke('${run.name}')`);
            }
        };
        /**
         * CLI lines for a durable run, in emission order.
         * @param events
         */
        function renderStepTimeline(events) {
            const lines = [];
            for (const event of events) {
                if (event.kind === 'log') {
                    lines.push(`${event.timestamp} ${event.level.toUpperCase()} ${event.message}`);
                    continue;
                }
                if (event.phase === 'start') {
                    // mark the start of the function being invoked.
                    if (event.kind === 'delegate') {
                        lines.push(`  ${STEP_PHASE_GLYPH[event.phase]} ${event.kind} -> ${event.name}`);
                    }
                    continue;
                }
                // Only show nested logs for invoked functions.
                // @todo: we may have to show for other events as we add more steps
                if (event.kind === 'delegate') {
                    logNestedRuns();
                }
                const glyph = STEP_PHASE_GLYPH[event.phase] ?? '•';
                const duration = typeof event.durationMs === 'number' ? ` (${Math.round(event.durationMs)}ms)` : '';
                const detail = event.phase === 'error' && event.error ? ` ${event.error.message}` : '';
                lines.push(`  ${glyph} ${event.name} [${event.kind}]${duration}${detail}`);
            }
            return lines;
        }
        const spinner = log.ora('Executing function...').start();
        const { json: response, logs, error, } = await testAction(resource, invokeOptions, context, {
            timeout: timeout ? timeout : resource.timeout,
            onNestedInvoke: runNested,
            depth: 0,
            callStack: [fnName],
            onStepEvent,
            noWait,
        });
        if (error) {
            spinner.fail('Function execution failed.');
            // Surface the function's own logs even on failure
            if (logs?.trim()) {
                log('Logs:');
                log(logs);
            }
            logNestedRuns();
            const errorMessage = error.stack || error.message || error.name;
            const isTimeout = error.message?.includes('Timeout');
            return {
                success: false,
                error: errorMessage,
                ref: isTimeout ? 'https://www.sanity.io/docs/help/functions-timeout' : undefined,
                suggestions: isTimeout
                    ? ['Increase the timeout in your Blueprint function configuration.']
                    : undefined,
            };
        }
        spinner.succeed('Function execution succeeded.');
        if (!plan.isDurable) {
            log('Logs:');
            log(logs || '');
            logNestedRuns();
            if (response) {
                log('Response:');
                log(JSON.stringify(response, null, 2));
            }
        }
        const durableResult = durableJson.result();
        return {
            success: true,
            json: plan.isDurable
                ? {
                    response: response ?? null,
                    steps: durableResult.steps,
                    logs: durableResult.logs,
                }
                : { response, logs },
        };
    }
    catch (error) {
        return {
            success: false,
            error: error instanceof Error ? error.message : String(error),
        };
    }
}
